import test from 'node:test';import assert from 'node:assert/strict';import {contactData,blockReason,phoneURI,emailURI,defaultDraft} from './assets/outreach-logic.mjs';
const record=()=>({stage:'Letter review',demo:false,checks:{ownership:true,authority:true,status:true,mail:true},verifiedAt:new Date().toISOString(),mail:'Fixture mailing address',address:'Fixture property'});
const contact=()=>contactData({recipient:'Fixture recipient',phone:'+18135550123',phoneVerified:true,email:'fixture@example.com',emailVerified:true,smsConsent:true,consentSource:'Fixture opt-in record',consentDate:'2026-01-01'});
test('Samples, do not contact, and stale checks block every outreach route',()=>{for(const channel of ['letter','call','sms','email']){assert.ok(blockReason({...record(),demo:true},contact(),channel));assert.ok(blockReason({...record(),stage:'Do not contact'},contact(),channel));assert.ok(blockReason({...record(),verifiedAt:'2020-01-01'},contact(),channel));assert.ok(blockReason(record(),{...contact(),suppressed:true},channel));}});
test('SMS requires documented consent beyond property verification',()=>{assert.equal(blockReason(record(),contact(),'sms'),'');assert.ok(blockReason(record(),{...contact(),smsConsent:false},'sms'));assert.ok(blockReason(record(),{...contact(),consentSource:''},'sms'));assert.ok(blockReason(record(),{...contact(),consentDate:'2999-01-01'},'sms'));});
test('Phone and email handoffs cannot accept arbitrary URL schemes',()=>{assert.equal(phoneURI('javascript:alert(1)'),'');assert.equal(emailURI('x@example.com?bcc=other@example.com','',''),'');assert.match(emailURI('fixture@example.com','Subject','Line\nTwo'),/^mailto:/);});
test('Backup hydration preserves drafts and history and bounds untrusted fields',()=>{const c=contactData({drafts:{letter:'Saved letter'},events:[{at:'2026-01-01',channel:'letter',outcome:'Downloaded'}],suppressed:true});assert.equal(c.drafts.letter,'Saved letter');assert.equal(c.events.length,1);assert.equal(c.suppressed,true);assert.equal(contactData(null).recipient,'');});
test('Templates use property and sender details without inferring distress',()=>{const s=defaultDraft('letter',record(),{name:'Ermias',business:'Baruch-Ermi LLC',reply:'fixture@example.com',returnAddress:'Fixture return address'});assert.match(s,/Fixture property/);assert.match(s,/Fixture return address/);assert.doesNotMatch(s,/probate|financially distressed/i);assert.match(defaultDraft('sms',record(),{}),/STOP/);});
